package com.universalplatform.integration;
import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="external_notification_provider",uniqueConstraints=@UniqueConstraint(name="uq_external_notification_tenant_key",columnNames={"tenant_id","provider_key"})) class ExternalNotificationProvider { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false,length=64) private String providerKey; @Column(nullable=false,length=24) private String providerType; @Column(nullable=false,length=1000) private String endpoint; @Column(length=500) private String credentialCiphertext; @Column(nullable=false) private boolean enabled; @Column(nullable=false) private Instant updatedAt; @Version private long version; protected ExternalNotificationProvider(){} ExternalNotificationProvider(UUID id,UUID tenantId,String key,String type,String endpoint,String credential,Instant now){this.id=id;this.tenantId=tenantId;this.providerKey=key;this.providerType=type;this.endpoint=endpoint;this.credentialCiphertext=credential;this.enabled=true;this.updatedAt=now;} UUID id(){return id;} UUID tenantId(){return tenantId;} String providerKey(){return providerKey;} String providerType(){return providerType;} String endpoint(){return endpoint;} String credentialCiphertext(){return credentialCiphertext;} boolean enabled(){return enabled;} long version(){return version;} void update(String type,String endpoint,String credential,Instant now){this.providerType=type;this.endpoint=endpoint;this.credentialCiphertext=credential;this.enabled=true;this.updatedAt=now;} void disable(){enabled=false;} }
